import{_ as e,o as n,c as t,a2 as s}from"./chunks/framework.D8Tso2Ul.js";const u=JSON.parse('{"title":"Módulo: Firmas Digitales","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/firmas.md","filePath":"modulos/firmas.md"}'),i={name:"modulos/firmas.md"};function d(o,a,r,l,c,p){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="modulo-firmas-digitales" tabindex="-1">Módulo: Firmas Digitales <a class="header-anchor" href="#modulo-firmas-digitales" aria-label="Permalink to &quot;Módulo: Firmas Digitales&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/components/SignaturePad.tsx</code> · <code>Backend/handlers/signatures/</code> · <code>lib/services/FirmaService</code></p><p>Sistema de firma electrónica que opera en línea y en terreno (offline), con registro inmutable de cada acto firmado.</p><div class="warning custom-block"><p class="custom-block-title">Consulta legal pendiente</p><p>La validez jurídica del PIN como firma electrónica ante un fiscalizador del DS 44 está siendo evaluada con la Dirección del Trabajo (acuerdo reunión CCHC 2026-06-10). <strong>No usar como única prueba legal</strong> hasta tener respuesta oficial. La implementación actual de <code>FirmaService</code> (PIN + token + IP + timestamp en <code>SignaturesTable</code>) <strong>no debe modificarse</strong> hasta entonces. Ver <a href="/manual/ds44/firmas-digitales.html">Firmas digitales y DS44</a>.</p></div><h2 id="estrategias-de-firma" tabindex="-1">Estrategias de firma <a class="header-anchor" href="#estrategias-de-firma" aria-label="Permalink to &quot;Estrategias de firma&quot;">​</a></h2><p><code>FirmaService</code> usa un patrón de estrategia con cuatro métodos:</p><table tabindex="0"><thead><tr><th>Estrategia</th><th>Código</th><th>Cuándo se usa</th></tr></thead><tbody><tr><td>PIN</td><td><code>PIN</code></td><td>Firma estándar con PIN personal</td></tr><tr><td>Offline</td><td><code>OFFLINE</code></td><td>Firma en terreno sin conexión</td></tr><tr><td>Presencial</td><td><code>PRESENCIAL</code></td><td>Firma asistida ante relator/supervisor</td></tr><tr><td>Biométrica</td><td><code>BIOMETRIC</code></td><td>Reservada (stub) — no implementada</td></tr></tbody></table><h2 id="documento-de-obra-vs-documento-diario" tabindex="-1">Documento de obra vs. documento diario <a class="header-anchor" href="#documento-de-obra-vs-documento-diario" aria-label="Permalink to &quot;Documento de obra vs. documento diario&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspecto</th><th>Documento de obra</th><th>Documento diario</th></tr></thead><tbody><tr><td>Origen</td><td>Precreado por fase (DS 44)</td><td>Creado y asignado a personas</td></tr><tr><td>Firma</td><td>Según el documento</td><td>Firma individual del asignado</td></tr><tr><td>Notificación</td><td>No se asigna individualmente</td><td>Genera mensaje en bandeja de entrada</td></tr><tr><td>Estado</td><td>Cumplimiento por fase</td><td>pendiente → firmado</td></tr></tbody></table><h2 id="flujo-de-firma-estandar-documento-diario" tabindex="-1">Flujo de firma estándar (documento diario) <a class="header-anchor" href="#flujo-de-firma-estandar-documento-diario" aria-label="Permalink to &quot;Flujo de firma estándar (documento diario)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Prevencionista asigna el documento a una persona</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. EventBus emite &quot;document.assigned&quot; → notificación en InboxTable</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. La persona abre el documento y firma con su PIN</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. FirmaService valida el PIN (pinHash) y registra la firma</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. Registro inmutable en SignaturesTable (PIN + IP + timestamp)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>6. El estado de la asignación cambia a &quot;firmado&quot;</span></span></code></pre></div><h2 id="firma-presencial-del-relator" tabindex="-1">Firma presencial del relator <a class="header-anchor" href="#firma-presencial-del-relator" aria-label="Permalink to &quot;Firma presencial del relator&quot;">​</a></h2><p>En actividades como <code>CAPACITACION_SST</code> y <code>CHARLA_5MIN</code>, además de la firma de los asistentes se requiere la <strong>firma cruzada del relator</strong>, que certifica que la actividad se impartió efectivamente. Esto se registra con <code>tipoFirma: relator</code>.</p><h2 id="firma-offline-en-terreno" tabindex="-1">Firma offline en terreno <a class="header-anchor" href="#firma-offline-en-terreno" aria-label="Permalink to &quot;Firma offline en terreno&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. La persona firma en tablet/móvil sin conexión (SignaturePad)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. La firma se guarda cifrada (AES) en IndexedDB (cola local)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. Validación de identidad offline con hash de RUT + PIN temporal</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. Al recuperar conexión: sincronización por lotes con reintentos exponenciales</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. Resolución de conflictos por timestamp del servidor</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>6. Registro definitivo en SignaturesTable</span></span></code></pre></div><p>La app funciona como <strong>PWA</strong> con caché de recursos críticos, y muestra alertas visuales sobre firmas pendientes de sincronizar.</p><h2 id="registro-inmutable-signaturestable" tabindex="-1">Registro inmutable (SignaturesTable) <a class="header-anchor" href="#registro-inmutable-signaturestable" aria-label="Permalink to &quot;Registro inmutable (SignaturesTable)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>signatureId / personaId / personaRut</span></span>
<span class="line"><span>tipoFirma         trabajador | relator | supervisor</span></span>
<span class="line"><span>referenciaId      Documento o actividad firmada</span></span>
<span class="line"><span>fecha / horario / timestamp</span></span>
<span class="line"><span>ipAddress</span></span>
<span class="line"><span>metodoValidacion  PIN | OFFLINE | PRESENCIAL | BIOMETRIC</span></span>
<span class="line"><span>estado            valida | disputada | anulada</span></span></code></pre></div><h2 id="endpoints-relacionados" tabindex="-1">Endpoints relacionados <a class="header-anchor" href="#endpoints-relacionados" aria-label="Permalink to &quot;Endpoints relacionados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Acción</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/signatures</code></td><td>Registrar firma</td></tr><tr><td><code>GET</code></td><td><code>/signatures/{id}</code></td><td>Obtener firma</td></tr><tr><td><code>POST</code></td><td><code>/signatures/offline-buffer</code></td><td>Registrar firma capturada sin red</td></tr><tr><td><code>GET</code></td><td><code>/signatures/offline-queue</code></td><td>Consultar cola pendiente</td></tr><tr><td><code>POST</code></td><td><code>/signatures/offline-sync</code></td><td>Sincronizar lote</td></tr><tr><td><code>DELETE</code></td><td><code>/signatures/offline-queue/{id}</code></td><td>Limpiar elemento procesado</td></tr></tbody></table><p>Ver detalle en <a href="/manual/api/firmas.html">API · Firmas</a>.</p>`,21)])])}const h=e(i,[["render",d]]);export{u as __pageData,h as default};
